INSERT INTO `cds_correlation_rules` VALUES (1, 'Diabetes correlation: GLU and HbA1c', 42, '{\"op\": \"OR\", \"conditions\": [{\"value\": 11.1, \"operator\": \">=\", \"parameter_id\": 42}, {\"value\": 6.5, \"operator\": \">=\", \"parameter_id\": 45}]}', '42,45', 'Hyperglycemia or elevated HbA1c. Consider diabetes workup/confirmation.', 'ADD_COMMENT', NULL, 1, '2025-11-28 03:37:06', '2025-11-28 03:37:06');
INSERT INTO `cds_correlation_rules` VALUES (2, 'Critical Potassium Stop Auto-Verify', 31, '{\"op\": \"OR\", \"conditions\": [{\"value\": 2.5, \"operator\": \"<\", \"parameter_id\": 31}, {\"value\": 6.5, \"operator\": \">\", \"parameter_id\": 31}]}', '31', 'Critical K+. Verify sample and patient status immediately.', 'STOP_AUTO_VERIFY', NULL, 1, '2025-11-28 03:37:06', '2025-11-28 03:37:06');
INSERT INTO `cds_correlation_rules` VALUES (3, 'Transaminases both elevated', 20, '{\"op\": \"AND\", \"conditions\": [{\"value\": 41, \"operator\": \">\", \"parameter_id\": 20}, {\"value\": 40, \"operator\": \">\", \"parameter_id\": 21}]}', '20,21', 'ALT and AST elevated. Consider hepatic injury workup.', 'ADD_COMMENT', NULL, 1, '2025-11-28 03:37:06', '2025-11-28 03:37:06');
INSERT INTO `cds_correlation_rules` VALUES (4, 'Microcytic anemia reflex Ferritin', 3, '{\"op\": \"AND\", \"conditions\": [{\"value\": 120, \"operator\": \"<\", \"parameter_id\": 3}, {\"value\": 80, \"operator\": \"<\", \"parameter_id\": 6}]}', '3,6,58', 'Low HGB with low MCV. Reflex Ferritin suggested.', 'REFLEX_TEST', 58, 1, '2025-11-28 03:37:06', '2025-11-28 03:37:06');
INSERT INTO `cds_correlation_rules` VALUES (5, 'High TG note: LDL calculation unreliable', 34, '{\"op\": \">\", \"value\": 4.5, \"operator\": \">\", \"parameter_id\": 34}', '34,35,33', 'Triglycerides > 4.5 mmol/L — calculated LDL may be inaccurate.', 'ADD_COMMENT', NULL, 1, '2025-11-28 03:37:06', '2025-11-28 03:37:06');
INSERT INTO `cds_correlation_rules` VALUES (6, 'Sepsis markers high — manual review', 54, '{\"op\": \"OR\", \"conditions\": [{\"value\": 100, \"operator\": \">\", \"parameter_id\": 54}, {\"value\": 2, \"operator\": \">\", \"parameter_id\": 55}]}', '54,55', 'CRP/PCT markedly elevated. Manual review required.', 'STOP_AUTO_VERIFY', NULL, 1, '2025-11-28 03:37:06', '2025-11-28 03:37:06');
INSERT INTO `delta_check_actions` VALUES (1, 1, 'immediate', 'CRITICAL: Immediate verification required', 'Critical delta check violation detected', '[\"Repeat test with fresh sample\", \"Verify patient identity\", \"Check for pre-analytical errors\", \"Notify physician immediately\", \"Document all actions taken\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_actions` VALUES (2, 1, 'short_term', 'Critical Follow-up', 'Immediate follow-up actions', '[\"Monitor patient closely\", \"Consider additional testing\", \"Review with clinical team\", \"Update quality management system\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_actions` VALUES (3, 2, 'immediate', 'HIGH PRIORITY: Verification recommended', 'High priority delta check violation', '[\"Repeat test within 2 hours\", \"Verify sample integrity\", \"Check instrument calibration\", \"Review recent QC results\", \"Consider clinical correlation\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_actions` VALUES (4, 2, 'short_term', 'High Priority Follow-up', 'Short-term follow-up actions', '[\"Monitor trend over next 24-48 hours\", \"Consider additional testing if clinically indicated\", \"Review with clinical team\", \"Document in quality management system\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_actions` VALUES (5, 3, 'immediate', 'MODERATE: Review recommended', 'Moderate delta check violation', '[\"Verify test result\", \"Check instrument status\", \"Review patient history\", \"Consider repeat if clinically indicated\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_actions` VALUES (6, 3, 'short_term', 'Moderate Follow-up', 'Short-term monitoring', '[\"Monitor trend\", \"Review at next scheduled test\", \"Document findings\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_actions` VALUES (7, 4, 'immediate', 'LOW: Monitor trend', 'Low priority delta check observation', '[\"Document observation\", \"Continue routine monitoring\", \"Review at next scheduled test\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (1, 1, 'Significant changes may indicate diabetes control, stress response, or medication effects', '[\"Diabetes\", \"Medication changes\", \"Stress\", \"Infection\"]', '[\"Diabetes mellitus\", \"Hypoglycemia\", \"Hyperglycemia\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (2, 2, 'Significant changes may indicate bleeding, hemolysis, or treatment response', '[\"Bleeding\", \"Hemolysis\", \"Iron deficiency\", \"Chronic disease\"]', '[\"Anemia\", \"Polycythemia\", \"Hemorrhage\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (3, 3, 'Changes may reflect fluid status, blood loss, or hematologic disorders', '[\"Dehydration\", \"Blood loss\", \"Polycythemia\", \"Anemia\"]', '[\"Anemia\", \"Polycythemia\", \"Dehydration\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (4, 4, 'Variations may indicate fluid balance, kidney function, or endocrine disorders', '[\"Dehydration\", \"Heart failure\", \"Kidney disease\", \"SIADH\"]', '[\"Hyponatremia\", \"Hypernatremia\", \"SIADH\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (5, 5, 'Changes may reflect kidney function, medication effects, or acid-base status', '[\"Kidney disease\", \"Medications\", \"Acidosis\", \"Alkalosis\"]', '[\"Hyperkalemia\", \"Hypokalemia\", \"Kidney disease\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (6, 6, 'Changes may reflect kidney function, hydration status, or medication effects', '[\"Kidney disease\", \"Dehydration\", \"Medications\", \"Muscle mass changes\"]', '[\"Acute kidney injury\", \"Chronic kidney disease\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (7, 7, 'Significant changes may indicate myocardial injury or infarction', '[\"Chest pain\", \"Cardiac procedures\", \"Heart failure\", \"Kidney disease\"]', '[\"Myocardial infarction\", \"Unstable angina\", \"Heart failure\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_clinical_significance` VALUES (8, 8, 'Variations may indicate prostate disease progression or treatment response', '[\"Prostate procedures\", \"Prostatitis\", \"Age\", \"Family history\"]', '[\"Prostate cancer\", \"Benign prostatic hyperplasia\", \"Prostatitis\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_global_recommendations` VALUES (1, 'overall_violation_rate', 'violation_rate > 20', 'critical', 'High Overall Violation Rate', 'High overall violation rate detected', 'Immediate review of delta check limits and procedures required', '{\"violation_rate\": 20}', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_global_recommendations` VALUES (2, 'overall_violation_rate', 'violation_rate > 10', 'warning', 'Elevated Violation Rate', 'Elevated violation rate detected', 'Review delta check limits and quality control procedures', '{\"violation_rate\": 10}', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_global_recommendations` VALUES (3, 'parameter_specific', 'parameter_violation_rate > 30', 'warning', 'High Parameter Violation Rate', 'High violation rate for specific parameter', 'Review delta check limits for this parameter', '{\"parameter_violation_rate\": 30}', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (1, 'glucose', 'Blood Glucose', 'chemistry', 'mg/dL', 'Serum/Plasma', 10.00, NULL, 25.00, 'Blood glucose measurement for diabetes monitoring', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (2, 'hemoglobin', 'Hemoglobin', 'hematology', 'g/dL', 'Whole Blood', 7.00, 1.00, 15.00, 'Hemoglobin concentration in blood', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (3, 'hematocrit', 'Hematocrit', 'hematology', '%', 'Whole Blood', 6.00, 3.00, 12.00, 'Percentage of blood volume occupied by red blood cells', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (4, 'sodium', 'Sodium', 'chemistry', 'mEq/L', 'Serum', 5.00, 4.00, 10.00, 'Serum sodium concentration', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (5, 'potassium', 'Potassium', 'chemistry', 'mEq/L', 'Serum', 5.00, 0.50, 15.00, 'Serum potassium concentration', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (6, 'creatinine', 'Creatinine', 'chemistry', 'mg/dL', 'Serum', 15.00, 0.30, 30.00, 'Serum creatinine for kidney function assessment', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (7, 'troponin', 'Troponin I', 'cardiac', 'ng/mL', 'Serum', 20.00, 0.10, 50.00, 'Cardiac troponin for myocardial injury detection', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_parameters` VALUES (8, 'psa', 'Prostate Specific Antigen', 'tumor_marker', 'ng/mL', 'Serum', 20.00, 1.00, 40.00, 'PSA for prostate cancer screening and monitoring', '[\"CLIA\", \"CAP\", \"ISO 15189\"]', 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_preventive_measures` VALUES (1, 1, 'pre_analytical', 'Pre-analytical Measures for Glucose', 'Measures to prevent pre-analytical errors in glucose testing', '[\"Verify fasting status\", \"Check sample collection time\", \"Avoid hemolysis\", \"Ensure proper sample handling\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_preventive_measures` VALUES (2, 1, 'analytical', 'Analytical Measures for Glucose', 'Measures to ensure accurate glucose measurement', '[\"Check glucose meter calibration\", \"Verify reagent stability\", \"Monitor temperature\", \"Check for interference\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_preventive_measures` VALUES (3, 2, 'pre_analytical', 'Pre-analytical Measures for Hemoglobin', 'Measures to prevent pre-analytical errors in hemoglobin testing', '[\"Check for hemolysis\", \"Verify sample mixing\", \"Check anticoagulant\", \"Ensure proper collection\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_preventive_measures` VALUES (4, 2, 'analytical', 'Analytical Measures for Hemoglobin', 'Measures to ensure accurate hemoglobin measurement', '[\"Verify hematology analyzer\", \"Check for carryover\", \"Monitor QC results\", \"Verify calibration\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_quality_control` VALUES (1, 1, 'instrument_check', 'Glucose Instrument Check', 'Quality control checks for glucose instruments', '[\"Verify instrument calibration\", \"Check maintenance logs\", \"Review recent QC results\", \"Confirm method performance\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_quality_control` VALUES (2, 2, 'instrument_check', 'Hemoglobin Instrument Check', 'Quality control checks for hemoglobin instruments', '[\"Verify hematology analyzer\", \"Check for carryover\", \"Review QC results\", \"Confirm calibration\"]', 1, 1, '2025-11-20 04:05:28', '2025-11-20 04:05:28');
INSERT INTO `delta_check_quality_control` VALUES (3, NULL, 'instrument_check', 'Perform Instrument Maintenance', 'Ensure maintenance and calibration for all analyzers are performed as per manufacturer specifications before running QC.', '[\"Verify instrument logs and service schedules.\", \"Follow manufacturer maintenance checklist.\"]', 1, 1, '2025-11-26 06:36:09', '2025-11-26 06:36:09');
INSERT INTO `delta_check_quality_control` VALUES (4, NULL, 'qc_review', 'Use Appropriate Controls', 'QC materials should be appropriate for each test (lot number, expiration date, analyte coverage) and stored per manufacturer guidelines.', '[\"Check QC material lot and expiration before use.\", \"Store controls under recommended conditions.\"]', 2, 1, '2025-11-26 06:36:09', '2025-11-26 06:36:09');
INSERT INTO `delta_check_quality_control` VALUES (5, NULL, 'qc_review', 'Document All QC Issues and Corrections', 'All QC failures, corrective actions, and maintenance should be promptly documented in the LIS or QC log book for traceability.', '[\"Document failed QC flags immediately.\", \"Enter actions taken and personnel involved.\", \"Maintain clear audit trail for inspections.\"]', 3, 1, '2025-11-26 06:36:09', '2025-11-26 06:36:09');
INSERT INTO `delta_check_quality_control` VALUES (6, NULL, 'qc_review', 'Review QC Results Before Releasing Patient Results', 'Patient results must not be validated or released if associated QC fails or is under investigation. Confirm two levels of QC are in control.', '[\"Review QC data for all shifts and analyzers.\", \"Only release results if QC is verified and in range.\"]', 4, 1, '2025-11-26 06:36:09', '2025-11-26 06:36:09');
INSERT INTO `delta_check_quality_control` VALUES (7, NULL, 'corrective_action', 'Take Corrective Actions as per SOP for QC Failures', 'For any rule violation (e.g., 1-3s, 2-2s, R-4s), investigate, re-run controls, and document steps before rerunning patient samples. Take equipment out of service if necessary.', '[\"Review Westgard rule violations and root cause.\", \"Repeat QC, recalibrate, or replace reagents as needed.\", \"Escalate unresolved failures to senior staff or service.\", \"Never report results until QC passes.\"]', 5, 1, '2025-11-26 06:36:09', '2025-11-26 06:36:09');
