  `comparison_type` enum('percentage','absolute','both') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'both',
  `action_on_violation` enum('flag','flag_and_stop','alert_only') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'flag',
  `alert_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `severity_level_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `updated_by` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `delta_check_rules_severity_level_id_foreign`(`severity_level_id`) USING BTREE,
  INDEX `delta_check_rules_created_by_foreign`(`created_by`) USING BTREE,
  INDEX `delta_check_rules_updated_by_foreign`(`updated_by`) USING BTREE,
  INDEX `delta_check_rules_test_parameter_id_index`(`test_parameter_id`) USING BTREE,
  INDEX `delta_check_rules_analyzer_id_index`(`equipment_id`) USING BTREE,
  INDEX `delta_check_rules_is_active_index`(`is_active`) USING BTREE,
  CONSTRAINT `delta_check_rules_analyzer_id_foreign` FOREIGN KEY (`equipment_id`) REFERENCES `analyzers` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `delta_check_rules_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `delta_check_rules_severity_level_id_foreign` FOREIGN KEY (`severity_level_id`) REFERENCES `delta_check_severity_levels` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `delta_check_rules_test_parameter_id_foreign` FOREIGN KEY (`test_parameter_id`) REFERENCES `test_parameters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `delta_check_rules_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

