  `test_parameter_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `analyzer_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `quality_control_test_parameter_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `westgard_rule_type` enum('1-2s','1-3s','2-2s','R-4s','4-1s','10x') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `action_on_violation` enum('warning','reject','flag') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'reject',
  `severity_level` enum('info','warning','error','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'error',
  `alert_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `custom_threshold_multiplier` decimal(3, 2) NULL DEFAULT NULL COMMENT 'Override default SD multiplier (e.g., 2.5 for 2.5SD instead of 2SD)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `updated_by` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `qc_rules_created_by_foreign`(`created_by`) USING BTREE,
  INDEX `qc_rules_updated_by_foreign`(`updated_by`) USING BTREE,
  INDEX `qc_rules_test_parameter_id_index`(`test_parameter_id`) USING BTREE,
  INDEX `qc_rules_analyzer_id_index`(`analyzer_id`) USING BTREE,
  INDEX `qc_rules_quality_control_test_parameter_id_index`(`quality_control_test_parameter_id`) USING BTREE,
  INDEX `qc_rules_westgard_rule_type_index`(`westgard_rule_type`) USING BTREE,
  INDEX `qc_rules_is_active_index`(`is_active`) USING BTREE,
  INDEX `qc_rules_is_enabled_index`(`is_enabled`) USING BTREE,
  CONSTRAINT `qc_rules_analyzer_id_foreign` FOREIGN KEY (`analyzer_id`) REFERENCES `analyzers` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `qc_rules_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `qc_rules_quality_control_test_parameter_id_foreign` FOREIGN KEY (`quality_control_test_parameter_id`) REFERENCES `quality_control_test_parameter` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `qc_rules_test_parameter_id_foreign` FOREIGN KEY (`test_parameter_id`) REFERENCES `test_parameters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `qc_rules_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

