-- ----------------------------
-- Table structure for qc_sigma_metric_results
-- ----------------------------
DROP TABLE IF EXISTS `qc_sigma_metric_results`;
CREATE TABLE `qc_sigma_metric_results`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `test_parameter_id` bigint(0) UNSIGNED NOT NULL COMMENT 'The Analyte (test parameter) the Sigma Metric applies to',
  `sigma_metric` decimal(10, 4) NOT NULL COMMENT 'The calculated Σ value',
  `calculation_date` datetime(0) NOT NULL COMMENT 'Date/Time the metric was calculated',
  `observed_mean` decimal(10, 4) NULL DEFAULT NULL COMMENT 'The x̄ (observed mean) used in the calculation',
  `observed_std_dev` decimal(10, 4) NULL DEFAULT NULL COMMENT 'The s (observed standard deviation) used in the calculation',
  `target_mean` decimal(10, 4) NULL DEFAULT NULL COMMENT 'The μ (target mean) used in the calculation',
  `te_a` decimal(10, 4) NULL DEFAULT NULL COMMENT 'The TE_a value used in the calculation',
  `period_days` int(0) NULL DEFAULT NULL COMMENT 'Number of days of QC data used',
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `qc_sigma_metric_results_test_parameter_id_index`(`test_parameter_id`) USING BTREE,
  INDEX `qc_sigma_metric_results_calculation_date_index`(`calculation_date`) USING BTREE,
  INDEX `qc_sigma_metric_results_test_parameter_id_calculation_date_index`(`test_parameter_id`, `calculation_date`) USING BTREE,
  CONSTRAINT `qc_sigma_metric_results_test_parameter_id_foreign` FOREIGN KEY (`test_parameter_id`) REFERENCES `test_parameters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 132 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

