-- ----------------------------
-- Table structure for test_results
-- ----------------------------
DROP TABLE IF EXISTS `test_results`;
CREATE TABLE `test_results`  (
  `id` bigint(0) UNSIGNED NOT NULL AUTO_INCREMENT,
  `version` enum('R0','R1','R2') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'R0',
  `laboratory_request_id` bigint(0) UNSIGNED NOT NULL,
  `test_id` bigint(0) UNSIGNED NOT NULL,
  `result_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `result_comment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `status` enum('pending','saved','completed','validated','released','superseded','final','accepted') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `qc_lockout_active` tinyint(1) NOT NULL DEFAULT 0,
  `qc_lockout_date` timestamp(0) NULL DEFAULT NULL,
  `qc_corrective_action_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `requires_review` tinyint(1) NOT NULL DEFAULT 0,
  `performed_by` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `performed_at` timestamp(0) NULL DEFAULT NULL,
  `verified_by` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `verified_at` timestamp(0) NULL DEFAULT NULL,
  `created_at` timestamp(0) NULL DEFAULT NULL,
  `updated_at` timestamp(0) NULL DEFAULT NULL,
  `parent_result_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `test_parameter_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `equipment_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `performer_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `verifier_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  `pathologist_id` bigint(0) UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `test_results_laboratory_request_id_foreign`(`laboratory_request_id`) USING BTREE,
  INDEX `test_results_test_id_foreign`(`test_id`) USING BTREE,
  INDEX `test_results_performed_by_foreign`(`performed_by`) USING BTREE,
  INDEX `test_results_verified_by_foreign`(`verified_by`) USING BTREE,
  INDEX `test_results_parent_result_id_foreign`(`parent_result_id`) USING BTREE,
  INDEX `test_results_test_parameter_id_foreign`(`test_parameter_id`) USING BTREE,
  INDEX `test_results_performer_id_foreign`(`performer_id`) USING BTREE,
  INDEX `test_results_verifier_id_foreign`(`verifier_id`) USING BTREE,
  INDEX `test_results_pathologist_id_foreign`(`pathologist_id`) USING BTREE,
  INDEX `test_results_qc_corrective_action_id_foreign`(`qc_corrective_action_id`) USING BTREE,
  INDEX `test_results_equipment_id_foreign`(`equipment_id`) USING BTREE,
  CONSTRAINT `test_results_equipment_id_foreign` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_laboratory_request_id_foreign` FOREIGN KEY (`laboratory_request_id`) REFERENCES `laboratory_requests` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `test_results_parent_result_id_foreign` FOREIGN KEY (`parent_result_id`) REFERENCES `test_results` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_pathologist_id_foreign` FOREIGN KEY (`pathologist_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_performed_by_foreign` FOREIGN KEY (`performed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_performer_id_foreign` FOREIGN KEY (`performer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_qc_corrective_action_id_foreign` FOREIGN KEY (`qc_corrective_action_id`) REFERENCES `corrective_actions` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_test_id_foreign` FOREIGN KEY (`test_id`) REFERENCES `tests` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `test_results_test_parameter_id_foreign` FOREIGN KEY (`test_parameter_id`) REFERENCES `test_parameters` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `test_results_verifier_id_foreign` FOREIGN KEY (`verifier_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 304 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

